CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "phone" TEXT, "role" TEXT NOT NULL DEFAULT 'USER', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Listing" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "transactionType" TEXT NOT NULL, "propertyType" TEXT NOT NULL, "city" TEXT NOT NULL, "township" TEXT NOT NULL, "address" TEXT NOT NULL, "priceMmk" INTEGER NOT NULL, "rentalBillingPeriod" TEXT, "bedrooms" INTEGER, "bathrooms" INTEGER, "floorArea" INTEGER, "landArea" INTEGER, "furnishing" TEXT, "contactName" TEXT NOT NULL, "contactPhone" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "publishedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Listing_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ListingImage" ("id" TEXT NOT NULL PRIMARY KEY, "listingId" TEXT NOT NULL, "url" TEXT NOT NULL, "altText" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ListingImage_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "Listing"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Amenity" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL);
CREATE UNIQUE INDEX "Amenity_name_key" ON "Amenity"("name");
CREATE TABLE "ListingAmenity" ("listingId" TEXT NOT NULL, "amenityId" TEXT NOT NULL, PRIMARY KEY ("listingId", "amenityId"), CONSTRAINT "ListingAmenity_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "Listing"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ListingAmenity_amenityId_fkey" FOREIGN KEY ("amenityId") REFERENCES "Amenity"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AdminAuditLog" ("id" TEXT NOT NULL PRIMARY KEY, "adminId" TEXT NOT NULL, "action" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetId" TEXT NOT NULL, "metadata" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AdminAuditLog_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
